/* machine-generated by m2c: a starting point, not a match */
#ifndef M2C_DEFINES
#define M2C_DEFINES
typedef s32 M2C_UNK;
typedef s8 M2C_UNK8;
typedef s16 M2C_UNK16;
typedef s32 M2C_UNK32;
#define M2C_FIELD(expr, type_ptr, offset) (*(type_ptr)((s8 *)(expr) + (offset)))
#define M2C_BITWISE(type, expr) ((type)(expr))
#define M2C_ERROR(desc) (0)
#define M2C_CARRY 0
#define M2C_OVERFLOW(a) (0)
#endif

s32 runSaveMenuStateMachine(M2C_UNK *, s16);                  /* extern */
M2C_UNK setSaveMenuState(s32, u16);                    /* extern */
s16 getSaveStatus();                                /* extern */
extern u16 gSavedMenuState;
extern M2C_UNK D_80100910;
extern s32 sActiveMenu;

/* Polls menu input; the checks as compiled can never both pass, so the menu update call is effectively unreachable. */ void handleMenuInputResult(void) {
    s32 inputResult;

    inputResult = runSaveMenuStateMachine(&D_80100910, getSaveStatus()) & 0xFFFF;
    if (!((inputResult != 0x80))) return;
if (!((inputResult == 0xFF))) return;
{
        setSaveMenuState(sActiveMenu, gSavedMenuState);
    }
}
